    viz: { anim: 'lachman_error', muscles: [], inv: [...QUADS, ...HAM], joints: ['knee'], pain: ['kneeJ.r'], focus: 'knee', caption: 'Test Lachmana przy zerwanym ACL: piszczel przesuwa się wyraźnie do przodu względem kości udowej (w animacji przesadzone), koniec ruchu jest miękki. Czerwony – staw kolanowy z więzadłami.' },
