    objawy: ['Ból w szparze stawowej (przyśrodkowej lub bocznej).', 'Obrzęk narastający w ciągu doby.', 'Objawy mechaniczne: przeskakiwanie, blokowanie, „uciekanie”.', 'Ból przy głębokim przysiadzie i obrotach.'],
    badanie: ['Tkliwość szpary stawowej – najbardziej czuła.', 'Test McMurraya, test Thessaly (obrót na jednej nodze w zgięciu 20°).', 'Test Apleya.', 'MRI; u starszych z bólem zwyrodnieniowym MRI często pokazuje pęknięcia bez znaczenia klinicznego.'],
    tests: ['mcmurray', 'apley_knee'],
    roznic: ['Uszkodzenie więzadła pobocznego (ból wyżej / niżej od szpary, test koślawienia).', 'Gonartroza (starszy wiek, wzorzec torebkowy).', 'Ból rzepkowo-udowy (ból z przodu).', 'Ciało wolne w stawie.'],
    fizjo: ['Pęknięcia zwyrodnieniowe: najpierw ćwiczenia (porównywalne wyniki z artroskopią).', 'Urazowe pęknięcia u młodych z blokowaniem – konsultacja (szycie łąkotki, jeśli możliwe).', 'Po szyciu: ograniczone zgięcie i obciążenie przez kilka tygodni; po częściowym usunięciu – szybszy powrót.', 'Wzmacnianie czworogłowego, kontrola nerwowo-mięśniowa, trening funkcjonalny.'],
    flagi: 'Prawdziwe zablokowanie kolana (nie da się wyprostować) – pilna konsultacja; podejrzenie zakażenia.',
