    badanie: ['Palpacja dolnego bieguna rzepki.', 'Przysiad jednonóż na desce pochyłej (decline squat) – ból w punkcie.', 'Ocena wykonania skoków i lądowań, siły czworogłowego.', 'Kwestionariusz VISA-P do monitorowania.'],
    tests: ['slsquat', 'hop'],
    roznic: ['Ból rzepkowo-udowy (rozlany, nie punktowy).', 'Choroba Sindinga-Larsena-Johanssona (dzieci, dolny biegun rzepki).', 'Choroba Osgooda-Schlattera (guzowatość piszczeli).', 'Zapalenie kaletki przedrzepkowej.'],
    fizjo: ['Zarządzanie obciążeniem (mniej skoków, nie całkowity odpoczynek).', 'Ćwiczenia izometryczne (przeciwbólowo), potem ciężki opór wolny (heavy slow resistance), ćwiczenia ekscentryczne.', 'Stopniowe przywracanie obciążeń sprężystych (pliometria) i skoków.', 'Praca nad techniką lądowania, siłą bioder i łydek.'],
    flagi: 'Nagły ból z utratą wyprostu czynnego (zerwanie więzadła rzepki), obrzęk stawu.',
